SELECT products.supplier_id, CASE WHEN products.category IN ('Books', 'Home') THEN 'priority' ELSE 'other' END AS category_group, MAX(store_sales.units) AS max_units FROM store_sales FULL OUTER JOIN products ON store_sales.product_id = products.id WHERE MONTH(products.launch_date) IN (5, 6, 7) GROUP BY products.supplier_id, CASE WHEN products.category IN ('Books', 'Home') THEN 'priority' ELSE 'other' END;
